const t = $('Execute Workflow Trigger').first().json;
const banco = $('banco_info').first().json;
const rodadas = Number(t.rodadas_vagas) || 0;
const raw = $input.first().json || {};

// --- FORMA REAL da saida do no openAi v2.3 (resource=text, operation=response) ---
// simplify:true NAO colapsa esta forma. A saida vem como:
//   { output: [ { type:'message', content: [ { type:'output_text', text: <X> } ], role:'assistant' } ] }
// Com textFormat.type=json_schema, <X> ja vem PARSEADO como objeto. Sem schema, <X> e string.
function respText(r) {
  if (!r || typeof r !== 'object') return undefined;
  const out = r.output;
  if (!Array.isArray(out)) return undefined;
  for (let i = 0; i < out.length; i++) {
    const msg = out[i];
    if (!msg || typeof msg !== 'object') continue;
    const content = msg.content;
    if (Array.isArray(content)) {
      for (let j = 0; j < content.length; j++) {
        const part = content[j];
        if (part && typeof part === 'object' && part.text !== undefined && part.text !== null) return part.text;
      }
    }
    if (msg.text !== undefined && msg.text !== null) return msg.text;
  }
  return undefined;
}

let c = raw;
if (raw && typeof raw === 'object') {
  if (raw.__sim_invalid) {
    c = {};
  } else {
    const rt = respText(raw);
    if (rt !== undefined) { c = rt; }
    else if (raw.message && typeof raw.message.content === 'string') { c = raw.message.content; }
    else if (typeof raw.content === 'string') { c = raw.content; }
    else if (typeof raw.output === 'string') { c = raw.output; }
    else if (typeof raw.text === 'string') { c = raw.text; }
    else if (raw.output && typeof raw.output === 'object' && !Array.isArray(raw.output)) { c = raw.output; }
  }
}
if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) { c = {}; } }
if (!c || typeof c !== 'object' || Array.isArray(c)) { c = {}; }

const classificacao = c.classificacao;
const valid = classificacao === 'emergencia' || classificacao === 'nao_emergencia' || classificacao === 'ambiguo';
const outputRaw = valid ? c : {};

const carry = {
  mensagem: t.mensagem,
  historico_texto: t.historico_texto || '',
  rodadas_vagas: rodadas,
  unidade: t.unidade || 'Unidade A',
  _classificador_input: { mensagem: t.mensagem, historico_texto: t.historico_texto || '' },
  _classificador_output_raw: outputRaw,
  _gate_input: ($('Pos-Gate Contextual').first().json || {})._gate_input || null,
  _gate_output_raw: ($('Pos-Gate Contextual').first().json || {})._gate_output_raw || null,
  banco_info: {
    HORARIO_CANONICO: banco.HORARIO_CANONICO,
    TELEFONE: banco.TELEFONE,
    ENDERECO: banco.ENDERECO,
    unidade: t.unidade || 'Unidade A'
  }
};

if (!valid) {
  return [{ json: Object.assign({}, carry, {
    classificacao: null,
    classificacao_real: 'classificador_invalido',
    emergencia: true,
    modo: 'emergencia',
    rota: 'compositor_emergencia',
    sub_modo: null,
    criterio_disparado: 'classificador_invalido',
    confianca: 'baixa',
    precisa_mais_info: false,
    intent: (c && c.intent) || 'relato_clinico',
    tem_pergunta_info: false,
    motivo_alerta: '⚠️ Classificador retornou saida invalida - triagem escalada por seguranca. Verifique o tutor manualmente AGORA.'
  }) }];
}

const criterio = (c.criterio_disparado === undefined ? null : c.criterio_disparado);
const precisaMais = c.precisa_mais_info === true;
const intent = c.intent || 'relato_clinico';
// Guardrail deterministico: pergunta clinica/medicacao nao e pergunta sobre a clinica.
const msgNorm = String(t.mensagem || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();
const perguntaInfoDeterministica = intent === 'relato_clinico' && (
  /\bque\s+horas?\b/.test(msgNorm) ||
  /\bhorario\b/.test(msgNorm) ||
  /\bhora\s+(?:que|de)\b/.test(msgNorm) ||
  /\b(?:abre|abrem|aberto|aberta|abertos|abertas|fecha|fecham|fechado|fechada)\b/.test(msgNorm) ||
  /\bfuncionamento\b/.test(msgNorm) ||
  /\b(?:estao|esta|tao|ta)\s+atendendo\b/.test(msgNorm) ||
  /\bendereco\b/.test(msgNorm) ||
  /\bonde\s+fica\b/.test(msgNorm) ||
  /\bcomo\s+chegar\b/.test(msgNorm) ||
  /\btelefone\b/.test(msgNorm) ||
  /\bnumero\s+(?:da|de)\s+clinica\b/.test(msgNorm) ||
  /\bcontato\s+(?:da|de)\s+clinica\b/.test(msgNorm)
);
const temPerg = perguntaInfoDeterministica;
const clinico = intent === 'relato_clinico' || temPerg || criterio != null;

// CONCERN-4: um cumprimento puro ("oi", "boa noite") no turno atual e SEMPRE saudacao.
// Mesmo que o Classificador venha com classificacao='ambiguo' / precisa_mais_info=true
// influenciado por uma emergencia anterior no historico, o historico e so contexto --
// nao transforma um "oi" em pergunta clinica nem em emergencia.
const saudacaoPura = intent === 'saudacao' && !clinico;

let modo; let emergencia; let classificacao_real = classificacao; let criterio_disparado = criterio;
let precisaMaisEff = precisaMais;

if (saudacaoPura) {
  modo = 'final'; emergencia = false; precisaMaisEff = false;
  if (classificacao !== 'nao_emergencia') { classificacao_real = 'nao_emergencia'; }
} else if (classificacao === 'emergencia') {
  modo = 'emergencia'; emergencia = true;
} else if (classificacao === 'ambiguo') {
  if (precisaMais && rodadas < 3) { modo = 'pergunta'; emergencia = false; }
  else { modo = 'emergencia'; emergencia = true; criterio_disparado = criterio_disparado || 'ambiguo_vies_escalar'; }
} else {
  if (clinico && precisaMais && rodadas < 3) { modo = 'pergunta'; emergencia = false; }
  else if (clinico && precisaMais && rodadas >= 3) { modo = 'emergencia'; emergencia = true; classificacao_real = 'ambiguo'; criterio_disparado = 'cap_rodadas_vagas'; }
  else { modo = 'final'; emergencia = false; }
}

let rota;
if (modo === 'emergencia') { rota = 'compositor_emergencia'; }
else if (modo === 'pergunta') { rota = 'compositor_nao_emergencia'; }
else if (modo === 'final' && intent === 'info_horario' && !clinico) { rota = 'template_horario'; }
else { rota = 'compositor_nao_emergencia'; }

let sub_modo = null;
if (rota === 'compositor_nao_emergencia') {
  if (modo === 'pergunta') { sub_modo = 'pergunta'; }
  else if (intent === 'saudacao' && !clinico) { sub_modo = 'saudacao'; }
  else if (intent === 'fora_escopo' && !clinico) { sub_modo = 'deflexao'; }
  else { sub_modo = 'orientacao'; }
}

return [{ json: Object.assign({}, carry, {
  classificacao,
  classificacao_real,
  emergencia,
  modo,
  rota,
  sub_modo,
  criterio_disparado: (criterio_disparado === undefined ? null : criterio_disparado),
  confianca: c.confianca || 'media',
  precisa_mais_info: precisaMaisEff,
  intent,
  tem_pergunta_info: temPerg,
  motivo_alerta: null
}) }];

