const pr = $('Pos-Regra').first().json;
const banco = pr.banco_info || {};
const horario = banco.HORARIO_CANONICO || 'Segunda a sexta: 08h às 20h. Sábado: 08h às 13h. Domingo: fechado.';
const tel = banco.TELEFONE || '';
const texto = 'Oi! Nosso horário de funcionamento: ' + horario + (tel ? ' Telefone: ' + tel + '.' : '') + ' Qualquer coisa urgente com o seu pet, é só me contar.';
return [{ json: { _template_text: texto, output: texto } }];

const pr = $('Pos-Regra').first().json;
const raw = $input.first().json || {};

// --- FORMA REAL da saida do no openAi v2.3 (resource=text, operation=response) ---
// { output: [ { type:'message', content: [ { type:'output_text', text: '<STRING>' } ], role:'assistant' } ] }
// simplify:true NAO colapsa. template_horario devolve {_template_text, output} (strings) e cai no fallback.
function respText(r) {
  if (!r || typeof r !== 'object') return undefined;
  const out = r.output;
  if (!Array.isArray(out)) return undefined;
  for (let i = 0; i < out.length; i++) {
    const msg = out[i];
    if (!msg || typeof msg !== 'object') continue;
    const content = msg.content;
    if (Array.isArray(content)) {
      for (let j = 0; j < content.length; j++) {
        const part = content[j];
        if (part && typeof part === 'object' && part.text !== undefined && part.text !== null) return part.text;
      }
    }
    if (msg.text !== undefined && msg.text !== null) return msg.text;
  }
  return undefined;
}

let texto = '';
const rt = respText(raw);
if (typeof rt === 'string') { texto = rt; }
else if (rt && typeof rt === 'object' && typeof rt.text === 'string') { texto = rt.text; }
else if (typeof raw === 'string') { texto = raw; }
else if (typeof raw._template_text === 'string') { texto = raw._template_text; }
else if (typeof raw.output === 'string') { texto = raw.output; }
else if (typeof raw.content === 'string') { texto = raw.content; }
else if (typeof raw.text === 'string') { texto = raw.text; }
else if (raw.message && typeof raw.message.content === 'string') { texto = raw.message.content; }
else if (raw.output && typeof raw.output === 'object' && !Array.isArray(raw.output) && typeof raw.output.text === 'string') { texto = raw.output.text; }
texto = (texto || '').trim();

const texto_llm_ok = texto.length > 0;

if (!texto) {
  texto = pr.emergencia
    ? 'Já estou acionando a equipe de plantão pra te ajudar agora, aguarda só um instante.'
    : 'Recebi a sua mensagem. Assim que a clínica abrir, procure a equipe para avaliar o seu pet com calma.';
}

const nome = pr.rota;
// injetouBanco: flag do Classificador + defesa em profundidade por regex no texto do tutor (CONCERN-1,
// dev-update 2026-09-01). IDENTICO ao de 'Prep Nao-Emergencia'. Single source of truth do gate.
const _msgTutor = String(pr.mensagem || (pr._classificador_input && pr._classificador_input.mensagem) || '');
const _askInfoRe = /horári|\bhora|abre|fecha|funciona|abert|endere[çc]|telefone|contato/i;
const injetouBanco = ((pr.tem_pergunta_info === true) || (pr.intent === 'info_horario')) && _askInfoRe.test(_msgTutor);

// Anexo deterministico do horario canonico byte-exato quando o tutor perguntou horario
// e a rota e o Compositor Nao-Emergencia. O compositor e instruido a NAO escrever a grade
// (garantia dura AC-2 / classe do incidente 2026-07-29 -- LLM parafraseia).
// Rota compositor_emergencia: o anexo NAO dispara -- a pergunta de horario numa emergencia
// e respondida por redirecionamento no prompt do Compositor Emergencia (spec 12.6 / CONCERN-2).
let outputFinal = texto;
const horarioAnexado = injetouBanco && nome === 'compositor_nao_emergencia';
if (horarioAnexado) {
  const hc = (pr.banco_info && pr.banco_info.HORARIO_CANONICO) || '';
  if (hc && outputFinal.indexOf(hc) === -1) {
    outputFinal = (outputFinal ? outputFinal + '\n\n' : '') + 'Horário de funcionamento: ' + hc;
  }
}

const compositorInput = nome === 'template_horario'
  ? { sub_modo: null, intent: pr.intent, historico_texto: pr.historico_texto, banco_info: pr.banco_info }
  : { sub_modo: (pr.sub_modo === undefined ? null : pr.sub_modo), intent: pr.intent, historico_texto: pr.historico_texto, banco_info: injetouBanco ? pr.banco_info : null };

return [{ json: {
  classificacao: pr.classificacao,
  classificacao_real: pr.classificacao_real,
  emergencia: pr.emergencia === true,
  modo: pr.modo,
  criterio_disparado: (pr.criterio_disparado === undefined ? null : pr.criterio_disparado),
  confianca: pr.confianca,
  precisa_mais_info: pr.precisa_mais_info === true,
  intent: pr.intent,
  tem_pergunta_info: pr.tem_pergunta_info === true,
  motivo_alerta: (pr.motivo_alerta === undefined ? null : pr.motivo_alerta),
  output: outputFinal,
  decisao_contextual: pr.decisao_contextual || (($('Pos-Gate Contextual').first().json || {}).decisao_contextual) || 'triagem',
  confianca_contextual: (($('Pos-Gate Contextual').first().json || {}).confianca_contextual) || null,
  motivo_contextual: (($('Pos-Gate Contextual').first().json || {}).motivo_contextual) || null,
  _captura: {
    gate_contextual: { input: pr._gate_input || null, output_raw: pr._gate_output_raw || null },
    classificador: { input: pr._classificador_input, output_raw: pr._classificador_output_raw },
    compositor: { nome: nome, input: compositorInput, output_raw: texto, texto_llm_ok: texto_llm_ok, horario_anexado: horarioAnexado }
  }
} }];

