// Prep Nao-Emergencia -- banco_info_block condicional (dev-fix etapa 7, Bug 3
// + CONCERN-1 dev-update 2026-09-01: defesa em profundidade contra tem_pergunta_info false-positive).
// injetouBanco IDENTICO ao de 'Normaliza Saida':
//   (tem_pergunta_info === true || intent === 'info_horario') && regex(mensagem do tutor)
// A regex exige que o TEXTO do tutor realmente contenha uma pergunta de horario/endereco/telefone --
// so o flag do Classificador nao basta (CLF-055: pergunta retorica marcava o flag e anexava a grade).
// OFF: nenhum dado de horario/telefone/endereco no prompt.
// ON: telefone/endereco/unidade no prompt; a GRADE de horario NAO vai no prompt --
//     'Normaliza Saida' anexa HORARIO_CANONICO byte-exato ao final (garantia dura AC-2,
//     classe do incidente 2026-07-29 -- o LLM parafraseia a grade).
const j = $input.first().json || {};
const bi = j.banco_info || {};
const msg = String(j.mensagem || '');
const askInfoRe = /horári|\bhora|abre|fecha|funciona|abert|endere[çc]|telefone|contato/i;
const injetouBanco = ((j.tem_pergunta_info === true) || (j.intent === 'info_horario')) && askInfoRe.test(msg);

const banco_info_block = injetouBanco
  ? ('Dados da clínica (fonte ÚNICA — nunca use conhecimento próprio; só cite o que o tutor perguntou):\n'
     + '- Telefone: ' + (bi.TELEFONE || '') + '\n'
     + '- Endereço: ' + (bi.ENDERECO || '') + '\n'
     + '- Unidade: ' + (bi.unidade || '') + '\n'
     + 'O tutor perguntou sobre horário/funcionamento. NÃO escreva a grade de horário você mesmo — ela é anexada automaticamente ao final. NÃO deflita a pergunta de horário (não diga "a recepção informa"); pode dizer algo curto como "o horário completo segue logo abaixo". Trate a queixa clínica normalmente.')
  : '(Sem dados de horário, telefone ou endereço nesta resposta — não mencione, cite nem invente horário, telefone ou endereço da clínica; apenas trate a queixa.)';

return [{ json: Object.assign({}, j, { banco_info_block: banco_info_block }) }];

